#if PERSONAL_APPS
#if os(iOS)
import Foundation
import Metal
import simd

/// The manifest is generated by scripts/tutu-skin/unlock-bake, never by the app.
final class TutuUnlockBaked: @unchecked Sendable {
    struct Image: Decodable {
        let url: String
        let rect: [Double]
        let shadowOffset: [Double]?
    }
    struct Frame: Decodable { let color: Image?; let shadow: Image? }
    struct Manifest: Decodable {
        struct Intro: Decodable { let start, end, fps: Double; let frames: [Frame]; let times: [Double] }
        struct Hanging: Decodable { let kick0, kick1: [Frame] }
        struct Carry: Decodable {
            let fps: Double
            let times: [Double]
            let frames: [Frame]
            let crossfade: Double
        }
        struct Rope: Decodable {
            let tile, cap, grip: Frame
            let tilePeriod, capEnd, gripStart: Double
        }
        let version: Int
        let format: String
        let density, supersampling, phasePeriod, phaseFPS: Double
        let phaseCount: Int
        let intro: Intro
        let hanging: Hanging
        let carry: Carry
        let rope: Rope
    }
    struct Statistics: Encodable {
        var loadMilliseconds = 0.0
        var uploadMilliseconds = 0.0
        var loadedImages = 0
        var textureBytes = 0
        var allocatedTextureBytes = 0
        var loadedOnMainThread = false
    }
    enum Failure: LocalizedError {
        case manifest, notPrepared, releasePose
        var errorDescription: String? {
            switch self {
            case .manifest: return "解锁预烤帧清单不完整或版本不匹配"
            case .notPrepared: return "解锁预烤帧尚未在后台准备完成"
            case .releasePose: return "解锁松手姿态尚未捕获"
            }
        }
    }
    private final class Store: @unchecked Sendable {
        let device: MTLDevice
        let root: URL
        let manifest: Manifest
        let textures: [String: MTLTexture]
        let statistics: Statistics
        init(device: MTLDevice, root: URL, checkCancellation: () throws -> Void) throws {
            let began = CFAbsoluteTimeGetCurrent()
            self.device = device; self.root = root
            manifest = try JSONDecoder().decode(Manifest.self, from: Data(contentsOf: root.appendingPathComponent("manifest.json")))
            let m = manifest
            func validTimes(_ times: [Double], frames: [Frame]) -> Bool {
                times.count == frames.count && times.count > 1
                    && zip(times, times.dropFirst()).allSatisfy { $0.0 < $0.1 }
            }
            guard m.version == 3, m.format == "astc", m.density == 3, m.supersampling == 4,
                  m.phasePeriod == 14.5, m.phaseCount > 1,
                  abs(m.phaseFPS - Double(m.phaseCount) / m.phasePeriod) < 1e-8,
                  m.intro.start == 3.45, m.intro.end == 5.32, m.intro.fps == 60,
                  validTimes(m.intro.times, frames: m.intro.frames),
                  m.intro.times.first == m.intro.start, m.intro.times.last == m.intro.end,
                  m.hanging.kick0.count == m.phaseCount, m.hanging.kick1.count == m.phaseCount,
                  m.carry.fps == 60, m.carry.crossfade == 0.12,
                  validTimes(m.carry.times, frames: m.carry.frames), m.carry.times.first == 0,
                  m.rope.tilePeriod > 0 else { throw Failure.manifest }
            let frames = m.intro.frames + m.hanging.kick0 + m.hanging.kick1 + m.carry.frames
                + [m.rope.tile, m.rope.cap, m.rope.grip]
            var bank: [String: MTLTexture] = [:]
            var stats = Statistics()
            stats.loadedOnMainThread = Thread.isMainThread
            for frame in frames {
                for image in [frame.color, frame.shadow].compactMap({ $0 }) {
                    try checkCancellation()
                    guard bank[image.url] == nil else { continue }
                    guard image.rect.count == 4, image.rect[2] > 0, image.rect[3] > 0,
                          image.shadowOffset == nil || image.shadowOffset?.count == 2 else { throw Failure.manifest }
                    let uploadStart = CFAbsoluteTimeGetCurrent()
                    let (texture, bytes) = try Self.upload(device: device, url: root.appendingPathComponent(image.url))
                    bank[image.url] = texture
                    stats.loadedImages += 1
                    stats.textureBytes += bytes
                    stats.allocatedTextureBytes += texture.allocatedSize
                    stats.uploadMilliseconds += (CFAbsoluteTimeGetCurrent() - uploadStart) * 1000
                }
            }
            textures = bank
            stats.loadMilliseconds = (CFAbsoluteTimeGetCurrent() - began) * 1000
            statistics = stats
        }
        private static func upload(device: MTLDevice, url: URL) throws -> (MTLTexture, Int) {
            let data = try Data(contentsOf: url, options: .mappedIfSafe)
            guard data.count >= 16 else { throw Failure.manifest }
            return try data.withUnsafeBytes { (bytes: UnsafeRawBufferPointer) in
                guard bytes[0] == 0x13, bytes[1] == 0xab, bytes[2] == 0xa1, bytes[3] == 0x5c,
                      bytes[6] == 1 else { throw Failure.manifest }
                func dimension(_ offset: Int) -> Int {
                    Int(bytes[offset]) | Int(bytes[offset + 1]) << 8 | Int(bytes[offset + 2]) << 16
                }
                let blockX = Int(bytes[4]), blockY = Int(bytes[5])
                let width = dimension(7), height = dimension(10)
                guard width > 0, height > 0, dimension(13) == 1 else { throw Failure.manifest }
                let format: MTLPixelFormat
                switch (blockX, blockY) {
                case (4, 4): format = .astc_4x4_ldr
                case (5, 4): format = .astc_5x4_ldr
                case (5, 5): format = .astc_5x5_ldr
                case (6, 5): format = .astc_6x5_ldr
                case (6, 6): format = .astc_6x6_ldr
                case (8, 5): format = .astc_8x5_ldr
                case (8, 6): format = .astc_8x6_ldr
                case (8, 8): format = .astc_8x8_ldr
                case (10, 5): format = .astc_10x5_ldr
                case (10, 6): format = .astc_10x6_ldr
                case (10, 8): format = .astc_10x8_ldr
                case (10, 10): format = .astc_10x10_ldr
                case (12, 10): format = .astc_12x10_ldr
                case (12, 12): format = .astc_12x12_ldr
                default: throw Failure.manifest
                }
                let rowBytes = ((width + blockX - 1) / blockX) * 16
                let payloadBytes = rowBytes * ((height + blockY - 1) / blockY)
                guard data.count == 16 + payloadBytes else { throw Failure.manifest }
                let descriptor = MTLTextureDescriptor.texture2DDescriptor(pixelFormat: format, width: width, height: height, mipmapped: false)
                descriptor.storageMode = .shared; descriptor.usage = .shaderRead
                guard let texture = device.makeTexture(descriptor: descriptor) else { throw TutuUnlockError.allocation }
                texture.label = url.lastPathComponent
                texture.replace(region: MTLRegionMake2D(0, 0, width, height), mipmapLevel: 0,
                                withBytes: bytes.baseAddress!.advanced(by: 16), bytesPerRow: rowBytes)
                return (texture, payloadBytes)
            }
        }
        func texture(_ image: Image) throws -> MTLTexture {
            guard let texture = textures[image.url] else { throw Failure.notPrepared }
            return texture
        }
    }
    private struct Sample { let image: Image; let weight: Double }
    private struct Layer { let samples: [Sample]; let ropePart: Int?; let shadow: Bool }
    private struct PreparedLayer { let layer: Layer; let textures: [MTLTexture] }
    private struct Prepared { let time, wave, kick: Double; let layers: [PreparedLayer] }
    private struct ReleasePose { let time, kick: Double }
    // Four adjacent hanging samples plus two elapsed-carry samples, blended in one pass.
    private static let sampleCapacity = 6
    private typealias SampleVectors = (SIMD4<Float>, SIMD4<Float>, SIMD4<Float>, SIMD4<Float>, SIMD4<Float>, SIMD4<Float>)
    private struct Uniforms {
        var bounds: SIMD4<Float>
        var transform: SIMD4<Float>
        var rects: SampleVectors
        var shifts: SampleVectors
        var weights: (SIMD4<Float>, SIMD4<Float>)
        var options: SIMD4<Float>
        var clip: SIMD4<Float>
    }
    private static let resourceWorker = DispatchQueue(label: "MemoryPalace.Tutu.unlock-residency", qos: .userInitiated)
    private static let sharedLock = NSLock()
    private static let creationLock = NSLock()
    private static var sharedStore: Store?
    private static var activationGeneration: UInt64 = 0
    private static var residencyActive = false
    private let store: Store
    private let pipeline: MTLRenderPipelineState
    private let preparedLock = NSLock()
    private var cancelled = false
    private var prepared: Prepared?
    private var releasePose: ReleasePose?
    var statistics: Statistics { store.statistics }
    private static func acquire(device: MTLDevice, resourceURL: URL, activationToken: UInt64? = nil) throws -> Store {
        creationLock.lock(); defer { creationLock.unlock() }
        let root = resourceURL.appendingPathComponent("TutuSkin/unlock/baked").resolvingSymlinksInPath()
        sharedLock.lock()
        if let activationToken, activationGeneration != activationToken {
            sharedLock.unlock(); throw CancellationError()
        }
        if let s = sharedStore, s.device.registryID == device.registryID, s.root == root {
            sharedLock.unlock(); return s
        }
        sharedLock.unlock()
        let candidate = try Store(device: device, root: root) {
            guard let activationToken else { return }
            sharedLock.lock(); let current = activationGeneration == activationToken; sharedLock.unlock()
            guard current else { throw CancellationError() }
        }
        sharedLock.lock(); defer { sharedLock.unlock() }
        if let activationToken, activationGeneration != activationToken { throw CancellationError() }
        if residencyActive { sharedStore = candidate }
        return candidate
    }
    private final class RetiredStore: @unchecked Sendable {
        var store: Store?
        init(_ store: Store?) { self.store = store }
        func release() { store = nil }
    }
    /// Called on activation/visibility changes; all disk IO and ASTC uploads stay on the worker.
    static func activationChanged(active: Bool) {
        sharedLock.lock()
        guard residencyActive != active else { sharedLock.unlock(); return }
        activationGeneration &+= 1
        let token = activationGeneration
        residencyActive = active
        let retired = active ? nil : sharedStore.map(RetiredStore.init)
        if !active { sharedStore = nil }
        sharedLock.unlock()
        guard active else {
            if let retired { resourceWorker.async { retired.release() } }
            return
        }
        resourceWorker.async {
            do {
                guard let device = MTLCreateSystemDefaultDevice(), let resources = Bundle.main.resourceURL else { throw TutuUnlockError.allocation }
                sharedLock.lock(); let current = activationGeneration == token; sharedLock.unlock()
                guard current else { return }
                _ = try acquire(device: device, resourceURL: resources, activationToken: token)
            } catch is CancellationError {
                // Leaving the scene invalidates the in-progress bank before publication.
            } catch {
                // Playback's resource preparation reports failures through the existing error UI.
                print("[TutuUnlock] prewarm: \(error)")
            }
        }
    }
    init(device: MTLDevice, library: MTLLibrary, resourceURL: URL, pixelFormat: MTLPixelFormat) throws {
        store = try Self.acquire(device: device, resourceURL: resourceURL)
        let d = MTLRenderPipelineDescriptor()
        d.vertexFunction = library.makeFunction(name: "tutuUnlockBakedVertex")
        d.fragmentFunction = library.makeFunction(name: "tutuUnlockBakedFragment")
        guard d.vertexFunction != nil, d.fragmentFunction != nil else { throw TutuUnlockError.shader("tutuUnlockBakedFragment") }
        let c = d.colorAttachments[0]!
        c.pixelFormat = pixelFormat; c.isBlendingEnabled = true
        c.sourceRGBBlendFactor = .one; c.destinationRGBBlendFactor = .oneMinusSourceAlpha
        c.sourceAlphaBlendFactor = .zero; c.destinationAlphaBlendFactor = .one
        pipeline = try device.makeRenderPipelineState(descriptor: d)
    }
    /// Capture before the model overwrites the hanging kick with its carried pose.
    func captureRelease(time: Double, kick: Double) {
        preparedLock.lock(); defer { preparedLock.unlock() }
        guard !cancelled else { return }
        releasePose = ReleasePose(time: time, kick: max(0, min(1, kick)))
    }
    private func timedFrames(_ frames: [Frame], times: [Double], at time: Double) -> [(Frame, Double)] {
        if time <= times[0] { return [(frames[0], 1)] }
        let last = times.count - 1
        if time >= times[last] { return [(frames[last], 1)] }
        var a = 0, b = last
        while b - a > 1 {
            let middle = (a + b) / 2
            if times[middle] <= time { a = middle } else { b = middle }
        }
        let mix = (time - times[a]) / (times[b] - times[a])
        return [(frames[a], 1 - mix), (frames[b], mix)]
    }
    private func hangingFrames(at time: Double, kick: Double) -> [(Frame, Double)] {
        let m = store.manifest
        let mix = max(0, min(1, kick))
        let wrapped = (time.truncatingRemainder(dividingBy: m.phasePeriod) + m.phasePeriod).truncatingRemainder(dividingBy: m.phasePeriod)
        let phase = wrapped * m.phaseFPS
        let base = floor(phase)
        let a = Int(base) % m.phaseCount, b = (a + 1) % m.phaseCount
        let f = phase - base
        return [(m.hanging.kick0[a], (1 - f) * (1 - mix)), (m.hanging.kick0[b], f * (1 - mix)),
                (m.hanging.kick1[a], (1 - f) * mix), (m.hanging.kick1[b], f * mix)]
    }
    private func rabbitFrames(_ v: TutuUnlockView) throws -> [(Frame, Double)] {
        guard let bunny = v.bunny else { return [] }
        let m = store.manifest
        if v.t < m.intro.end {
            return timedFrames(m.intro.frames, times: m.intro.times, at: v.t)
        }
        // wave==-1 is the model's sole pre-release sentinel; negative released wave is intentional.
        if v.wave == -1 { return hangingFrames(at: v.t, kick: bunny.rig.kick) }
        let elapsed = max(0, v.wave + 0.16)
        let carry = timedFrames(m.carry.frames, times: m.carry.times, at: elapsed)
        let mix = TutuUnlockModel.sstep(0, m.carry.crossfade, elapsed)
        if mix >= 1 { return carry }
        let releaseTime = v.t - elapsed
        preparedLock.lock(); let pose = releasePose; preparedLock.unlock()
        guard let pose, abs(pose.time - releaseTime) < 1e-8 else { throw Failure.releasePose }
        return hangingFrames(at: pose.time, kick: pose.kick).map { ($0.0, $0.1 * (1 - mix)) }
            + carry.map { ($0.0, $0.1 * mix) }
    }
    private func layers(_ view: TutuUnlockView) throws -> [Layer] {
        let rabbit = try rabbitFrames(view)
        var layers: [Layer] = []
        for shadow in [true, false] {
            if view.rope != nil {
                let r = store.manifest.rope
                for (part, f) in [r.cap, r.tile, r.grip].enumerated() {
                    if let i = shadow ? f.shadow : f.color { layers.append(Layer(samples: [Sample(image: i, weight: 1)], ropePart: part, shadow: shadow)) }
                }
            }
            let samples = rabbit.compactMap { f, w -> Sample? in
                guard w > 0, let i = shadow ? f.shadow : f.color else { return nil }
                return Sample(image: i, weight: w)
            }
            if !samples.isEmpty { layers.append(Layer(samples: samples, ropePart: nil, shadow: shadow)) }
        }
        return layers
    }
    /// Resident sample selection only; no IO, uploads, decoding, or eviction during playback.
    func prepare(view: TutuUnlockView) throws {
        let layers = try layers(view)
        let loaded = try layers.map { layer in PreparedLayer(layer: layer, textures: try layer.samples.map { try store.texture($0.image) }) }
        let frame = Prepared(time: view.t, wave: view.wave, kick: view.bunny?.rig.kick ?? 0, layers: loaded)
        preparedLock.lock()
        guard !cancelled else { preparedLock.unlock(); throw CancellationError() }
        prepared = frame
        preparedLock.unlock()
    }
    func cancel() {
        preparedLock.lock(); cancelled = true; prepared = nil; releasePose = nil; preparedLock.unlock()
    }
    func retainPrepared(until buffer: MTLCommandBuffer) {
        preparedLock.lock(); let frame = prepared; preparedLock.unlock()
        buffer.addCompletedHandler { _ in withExtendedLifetime(frame) {} }
    }
    func isReady(view: TutuUnlockView) throws -> Bool {
        preparedLock.lock(); defer { preparedLock.unlock() }
        guard let p = prepared else { return false }
        return p.time == view.t && p.wave == view.wave && p.kick == (view.bunny?.rig.kick ?? 0)
    }
    func requireReady(view: TutuUnlockView) throws { guard try isReady(view: view) else { throw Failure.notPrepared } }
    func encode(_ encoder: MTLRenderCommandEncoder, view: TutuUnlockView) throws {
        preparedLock.lock(); let frame = prepared; preparedLock.unlock()
        guard let frame, frame.time == view.t, frame.wave == view.wave else { throw Failure.notPrepared }
        encoder.setRenderPipelineState(pipeline)
        for p in frame.layers {
            let layer = p.layer
            guard !layer.samples.isEmpty, layer.samples.count <= Self.sampleCapacity,
                  p.textures.count == layer.samples.count else { throw Failure.manifest }
            let origin: SIMD2<Double>, angle: Double
            var clip = SIMD4<Float>.zero
            var period = 0.0
            if let part = layer.ropePart, let rope = view.rope {
                angle = -atan2(rope.u.x, rope.u.y)
                origin = part == 2 ? rope.S0 : rope.A
                if part == 1 {
                    let length = simd_dot(rope.S0 - rope.A, rope.u)
                    guard length > store.manifest.rope.capEnd - store.manifest.rope.gripStart else { continue }
                    clip = SIMD4(Float(store.manifest.rope.capEnd), Float(length + store.manifest.rope.gripStart), 1, 0)
                    if layer.shadow, let off = layer.samples.first?.image.shadowOffset {
                        let split = floor(off[1] * store.manifest.density) / store.manifest.density
                        clip.x += Float(split); clip.y += Float(split)
                    }
                    period = store.manifest.rope.tilePeriod
                }
            } else if let bunny = view.bunny {
                origin = SIMD2(bunny.origin.x, -bunny.origin.y)
                // R contains baked yaw/pitch; the rope supplies only the source's planar roll.
                let phi = view.rope.map { atan2($0.u.x, $0.u.y) } ?? 0
                angle = -phi * (view.t < 4.82 ? 0 : (view.t < 5.32 ? (view.t - 4.82) / 0.5 : 1))
            } else { continue }
            let c = cos(angle), s = sin(angle)
            func rotate(_ q: SIMD2<Double>) -> SIMD2<Double> { SIMD2(c * q.x - s * q.y, s * q.x + c * q.y) }
            var rects: SampleVectors = (.zero, .zero, .zero, .zero, .zero, .zero)
            var shifts = rects
            func set(_ tuple: inout SampleVectors, _ index: Int, _ value: SIMD4<Float>) {
                withUnsafeMutableBytes(of: &tuple) { $0.bindMemory(to: SIMD4<Float>.self)[index] = value }
            }
            var weights = (SIMD4<Float>.zero, SIMD4<Float>.zero)
            var bounds = SIMD4<Double>(.infinity, .infinity, -.infinity, -.infinity)
            for (i, sample) in layer.samples.enumerated() {
                let r = sample.image.rect
                var offset = SIMD2<Double>.zero
                if let off = sample.image.shadowOffset {
                    let world = SIMD2(off[0], off[1])
                    offset = SIMD2(c * world.x + s * world.y, -s * world.x + c * world.y) - world
                }
                set(&shifts, i, SIMD4(Float(offset.x), Float(offset.y), 0, 0))
                set(&rects, i, SIMD4(Float(r[0]), Float(r[1]), Float(r[2]), Float(r[3])))
                if i < 4 { weights.0[i] = Float(sample.weight) }
                else { weights.1[i - 4] = Float(sample.weight) }
                let y0 = period > 0 ? Double(clip.x) : r[1]
                let y1 = period > 0 ? Double(clip.y) : r[1] + r[3]
                for corner in 0..<4 {
                    let q = SIMD2(r[0] + ((corner & 1) == 0 ? 0 : r[2]), (corner & 2) == 0 ? y0 : y1)
                    let xy = origin + rotate(q + offset)
                    bounds.x = min(bounds.x, xy.x); bounds.y = min(bounds.y, xy.y)
                    bounds.z = max(bounds.z, xy.x); bounds.w = max(bounds.w, xy.y)
                }
            }
            let alpha = layer.shadow && view.wave >= 0 ? 1 - TutuUnlockModel.sstep(0, 0.4, view.wave) : 1
            let mask = layer.ropePart == nil && (view.bunny?.mask ?? 0) > 0.5 ? 809.3 : 1e9
            var u = Uniforms(bounds: SIMD4<Float>(bounds), transform: SIMD4(Float(origin.x), Float(origin.y), Float(c), Float(s)),
                rects: rects, shifts: shifts,
                weights: weights, options: SIMD4(Float(mask), Float(alpha), Float(period), Float(layer.samples[0].image.rect[1])), clip: clip)
            encoder.setVertexBytes(&u, length: MemoryLayout<Uniforms>.stride, index: 0)
            encoder.setFragmentBytes(&u, length: MemoryLayout<Uniforms>.stride, index: 0)
            for i in 0..<Self.sampleCapacity { encoder.setFragmentTexture(p.textures[min(i, p.textures.count - 1)], index: i) }
            encoder.drawPrimitives(type: .triangleStrip, vertexStart: 0, vertexCount: 4)
        }
    }
}
#endif
#endif
